"""Compare reports generated by separate published-package virtualenvs.

The legacy report intentionally shows unsafe request-derived cache reuse;
never assert parity for that bug or persistent raw ETag bytes.
"""

from __future__ import annotations

import json
from pathlib import Path
import sys


def main():
    if len(sys.argv) != 3:
        raise SystemExit("Usage: published_migration_compare.py legacy.json stable.json")
    legacy = json.loads(Path(sys.argv[1]).read_text())
    stable = json.loads(Path(sys.argv[2]).read_text())
    assert legacy["distribution"] == "fastapi-cache2"
    assert legacy["version"] == "0.2.2"
    assert stable["distribution"] == "fastapi-cache-stable"
    assert stable["version"] == "0.4.1"
    assert legacy["golden_default_key"] == stable["golden_default_key"]
    assert legacy["golden_default_key"] == (
        "migration-parity:ordinary:6c5186afe53d101dea5118bda9aebbcf"
    )
    for report in (legacy, stable):
        assert report["ordinary"] == ["MISS", "HIT"]
        assert report["sync"] == ["MISS", "HIT"]
        assert report["conditional_304"] == 304
        assert "site-packages" in report["module_location"]
    assert legacy["variant"]["values"] == ["en", "en"]
    assert stable["variant"]["values"] == ["en", "es"]
    assert legacy["authentication"]["values"] == [
        "Bearer Alice",
        "Bearer Alice",
    ]
    assert stable["authentication"]["values"] == [
        "Bearer Alice",
        "Bearer Bob",
    ]
    assert legacy["variant"]["statuses"] == ["MISS", "HIT"]
    assert stable["variant"]["statuses"] == [None, None]
    assert legacy["authentication"]["statuses"] == ["MISS", "HIT"]
    assert stable["authentication"]["statuses"] == [None, None]
    assert stable["error"]["http_statuses"] == [418, 418]
    assert stable["error"]["statuses"] == [None, None]
    assert stable["etag"].startswith('W/"')
    print("PASS: shared published legacy keys + GET/304 behavior")
    print("PASS: intentional safety divergences (auth, Request and non-200)")
    print("NOTE: ETags are intentionally not byte-identical between releases")


if __name__ == "__main__":
    main()
